  hezong_zhangyi_qiaoshe: {
    audio: 'ext:活动BOSS/audio/skill:true',
    trigger: {
      global: 'judge',
    },
    forced: true,
    content() {
      'step 0';
      const card = trigger.player.judging[0];
      const judge0 = trigger.judge(card);
      let judge1 = 0;
      let choice = trigger.no6 && card.number == 6 ? '+1' : 'cancel2';
      const attitude = get.attitude(player, trigger.player);
      const list = [];
      for (let i = -3; i < 4; i++) {
        if (i == 0) {
          continue;
        }
        list.push((i > 0 ? '+' : '') + i);
        if (!trigger.no6) {
          const judge2 =
            (trigger.judge({
              name: card.name,
              suit: card.suit,
              number: card.number + i,
              nature: get.nature(card),
            }) -
              judge0) *
            attitude;
          if (judge2 > judge1) {
            choice = (i > 0 ? '+' : '') + i;
            judge1 = judge2;
          }
        }
      }
      list.push('cancel2');
      player
        .chooseControl(list)
        .set('ai', function () {
          return _status.event.choice;
        })
        .set('choice', choice).prompt = get.prompt2(event.name);
      ('step 1');
      if (result.control != 'cancel2') {
        game.log(trigger.player, '判定结果点数', '#g' + result.control);
        player.popup(result.control, 'fire');
        if (!trigger.fixedResult) {
          trigger.fixedResult = {};
        }
        if (!trigger.fixedResult.number) {
          trigger.fixedResult.number = trigger.player.judging[0].number;
        }
        trigger.fixedResult.number += parseInt(result.control);
      }
    },
  },
