  shanhe_jiushi: {
    group: ['shanhe_jiushi1', 'shanhe_jiushi2', 'shanhe_jiushi3'],
  },
  shanhe_jiushi1: {
    enable: 'chooseToUse',
    hiddenCard(player, name) {
      if (name == 'jiu') {
        return !player.isTurnedOver();
      }
      return false;
    },
    filter(event, player) {
      if (player.classList.contains('turnedover')) {
        return false;
      }
      return event.filterCard({ name: 'jiu' }, player, event);
    },
    content() {
      if (_status.event.getParent(2).type == 'dying') {
        event.dying = player;
        event.type = 'dying';
      }
      player.turnOver();
      player.useCard({ name: 'jiu' }, player);
    },
    ai: {
      order: 5,
      result: {
        player(player) {
          if (_status.event.parent.name == 'phaseUse') {
            if (player.countCards('h', 'jiu') > 0) {
              return 0;
            }
            if (player.getEquip('zhuge') && player.countCards('h', 'sha') > 1) {
              return 0;
            }
            if (!player.countCards('h', 'sha')) {
              return 0;
            }
            const targets = [];
            let target;
            const players = game.filterPlayer();
            for (const i of players) {
              if (get.attitude(player, i) < 0) {
                if (player.canUse('sha', i, true, true)) {
                  targets.push(i);
                }
              }
            }
            if (targets.length) {
              target = targets[0];
            } else {
              return 0;
            }
            let num = get.effect(target, { name: 'sha' }, player, player);
            for (let i = 1; i < targets.length; i++) {
              const num2 = get.effect(targets[i], { name: 'sha' }, player, player);
              if (num2 > num) {
                target = targets[i];
                num = num2;
              }
            }
            if (num <= 0) {
              return 0;
            }
            const e2 = target.getEquip(2);
            if (e2) {
              if (e2.name == 'tengjia') {
                if (!player.countCards('h', { name: 'sha', nature: 'fire' }) && !player.getEquip('zhuque')) {
                  return 0;
                }
              }
              if (e2.name == 'renwang') {
                if (!player.countCards('h', { name: 'sha', color: 'red' })) {
                  return 0;
                }
              }
              if (e2.name == 'baiyin') {
                return 0;
              }
            }
            if (player.getEquip('guanshi') && player.countCards('he') > 2) {
              return 1;
            }
            return target.countCards('h') > 3 ? 0 : 1;
          }
          if (player == _status.event.dying || player.isTurnedOver()) {
            return 3;
          }
        },
      },
      effect: {
        target(card, player, target) {
          if (card.name == 'guiyoujie') {
            return [0, 0.5];
          }
          if (target.isTurnedOver()) {
            if (get.tag(card, 'damage')) {
              if ((player.hasSkillTag('jueqing', false, target) || player.hasSkill('shanhe_zhangdu')) && get.tag(card, 'damage')) {
                return [1, -2];
              }
              if (target.hp == 1) {
                return;
              }
              return [1, target.countCards('h') / 2];
            }
          }
        },
      },
    },
  },
