  qugui2_xingpan: {
    trigger: {
      player: 'phaseUseBegin',
    },
    filter(event, player) {
      return game.hasPlayer(function (current) {
        return player.getEnemies().includes(current) && current != player;
      });
    },
    forced: true,
    audio: 'ext:活动BOSS/audio/skill:true',
    content() {
      'step 0';
      event.target = [];
      game.countPlayer(function (current) {
        if (player.getEnemies().includes(current) && current != player) {
          event.target.push(current);
          event.xueliang = current.hp;
          event.shoupai = current.countCards('h');
          event.mubiao = current;
          event.mubiao2 = current;
        }
      });
      ('step 1');
      if (event.target.length) {
        for (const i of event.target) {
          if (event.xueliang < i.hp) {
            event.mubiao = i;
            event.xueliang = i.hp;
          } else {
            if (event.mubiao != i && event.xueliang == i.hp && event.mubiao) {
              delete event.mubiao;
            }
          }
          if (event.shoupai < i.countCards('h')) {
            event.mubiao2 = i;
            event.shoupai = i.countCards('h');
          } else {
            if (event.mubiao2 != i && event.shoupai == i.countCards('h') && event.mubiao2) {
              delete event.mubiao2;
            }
          }
        }
      }
      ('step 2');
      const func = function (result) {
        if (get.color(result) == 'red' && event.mubiao2) {
          return 10;
        }
        if (get.color(result) == 'black' && event.mubiao) {
          return 1;
        }
        return -1;
      };
      player.judge(func);
      ('step 3');
      event.color = result.color;
      if (event.color == 'red' && event.mubiao2) {
        if (event.shoupai % 2 == 0) {
          event.num = event.shoupai / 2;
        } else {
          event.num = (event.shoupai - 1) / 2;
        }
        if (event.num > 0) {
          event.mubiao2.chooseCard('〖刑判〗交给' + get.translation(player) + get.cnNumber(event.num) + '张手牌', true, event.num).set('ai', function (card) {
            return 7 - get.value(card);
          });
        }
      }
      if (event.color == 'black' && event.mubiao) {
        event.mubiao.loseHp();
        event.finish();
      }
      ('step 4');
      if (result.cards?.length) {
        player.gain(result.cards, event.mubiao2, 'giveAuto');
      }
    },
  },
