  boss_qice: {
    enable: 'phaseUse',
    usable: 1,
    audio: 'boss_qice_backup',
    filter(event, player) {
      const hs = player.getCards('h');
      if (!hs.length) {
        return false;
      }
      for (const i of hs) {
        const mod2 = game.checkMod(i, player, 'unchanged', 'cardEnabled2', player);
        if (mod2 === false) {
          return false;
        }
      }
      return true;
    },
    chooseButton: {
      dialog(player) {
        const list = [];
        for (const i of lib.inpile) {
          if (get.type(i) == 'trick') {
            list.push(['锦囊', '', i]);
          }
        }
        return ui.create.dialog(get.translation('boss_qice'), [list, 'vcard']);
      },
      filter(button, player) {
        return lib.filter.filterCard({ name: button.link[2] }, player, _status.event.parent);
      },
      check(button) {
        const player = _status.event.player;
        let recover = 0,
          lose = 1,
          players = game.filterPlayer();
        for (const i of players) {
          if (i.hp == 1 && get.damageEffect(i, player, player) > 0 && !i.hasSha()) {
            return button.link[2] == 'juedou' ? 2 : -1;
          }
          if (!i.isOut()) {
            if (i.hp < i.maxHp) {
              if (get.attitude(player, i) > 0) {
                if (i.hp < 2) {
                  lose--;
                  recover += 0.5;
                }
                lose--;
                recover++;
              } else if (get.attitude(player, i) < 0) {
                if (i.hp < 2) {
                  lose++;
                  recover -= 0.5;
                }
                lose++;
                recover--;
              }
            } else {
              if (get.attitude(player, i) > 0) {
                lose--;
              } else if (get.attitude(player, i) < 0) {
                lose++;
              }
            }
          }
        }
        if (lose > recover && lose > 0) {
          return button.link[2] == 'nanman' ? 1 : -1;
        }
        if (lose < recover && recover > 0) {
          return button.link[2] == 'taoyuan' ? 1 : -1;
        }
        return button.link[2] == 'wuzhong' ? 1 : -1;
      },
      backup(links, player) {
        return {
          filterCard: true,
          selectCard: -1,
          position: 'h',
          audio: 2,
          popname: true,
          viewAs: { name: links[0][2] },
        };
      },
      prompt(links, player) {
        return '将全部手牌当作' + get.translation(links[0][2]) + '使用';
      },
    },
    ai: {
      order: 1,
      result: {
        player(player) {
          let num = 0;
          const cards = player.getCards('h');
          if (cards.length >= 3 && player.hp >= 3 && !player.hasSkill('shanhe_hezhong')) {
            return 0;
          }
          if (Array.isArray(cards)) {
            for (const i of cards) {
              num += Math.max(0, get.value(i, player, 'raw'));
            }
          }
          num /= cards.length;
          num *= Math.min(cards.length, player.hp);
          return 12 - num + (player.hasSkill('shanhe_hezhong') ? 7 : 0);
        },
      },
      threaten: 1.6,
    },
  },
