  shanhe_ganlu: {
    enable: 'phaseUse',
    usable: 1,
    selectTarget: 2,
    filterTarget(card, player, target) {
      if (target.isMin()) {
        return false;
      }
      if (ui.selected.targets.length == 0) {
        return true;
      }
      if (ui.selected.targets[0].countCards('e') == 0 && target.countCards('e') == 0) {
        return false;
      }
      return Math.abs(ui.selected.targets[0].countCards('e') - target.countCards('e')) <= player.maxHp - player.hp;
    },
    multitarget: true,
    content() {
      targets[0].swapEquip(targets[1]);
    },
    ai: {
      order: 10,
      threaten(player, target) {
        return 0.8 * Math.max(1 + target.maxHp - target.hp);
      },
      result: {
        target(player, target) {
          const list1 = [];
          const list2 = [];
          const num = player.maxHp - player.hp;
          const players = game.filterPlayer();
          for (const i of players) {
            if (get.attitude(player, i) > 0) {
              list1.push(i);
            } else if (get.attitude(player, i) < 0) {
              list2.push(i);
            }
          }
          list1.sort(function (a, b) {
            return a.countCards('e') - b.countCards('e');
          });
          list2.sort(function (a, b) {
            return b.countCards('e') - a.countCards('e');
          });
          let delta;
          for (const i of list1) {
            for (const j of list2) {
              delta = j.countCards('e') - i.countCards('e');
              if (delta <= 0) {
                continue;
              }
              if (delta <= num) {
                if (target == i || target == j) {
                  return get.attitude(player, target);
                }
                return 0;
              }
            }
          }
          return 0;
        },
      },
      effect: {
        target(card, player, target) {
          if (target.hp == target.maxHp && get.tag(card, 'damage')) {
            return 0.2;
          }
        },
      },
    },
  },
