      let i = history.indexOf(evt);
      if (i == -1) {
        i = history.length - 1;
      } else {
        i--;
      }
      for (let i; i >= 0; i--) {
        if (history[i].source && player.getEnemies().includes(history[i].source) && history[i].source != player) {
          return history[i].source;
        }
      }
      return null;
