  shanhe_guixin: {
    trigger: {
      player: 'damageEnd',
    },
    check(event, player) {
      if (player.isTurnedOver() || event.num > 1) {
        return true;
      }
      const num = game.countPlayer(function (current) {
        if (current.countCards('he') && current != player && get.attitude(player, current) <= 0) {
          return true;
        }
        if (current.countCards('j') && current != player && get.attitude(player, current) > 0) {
          return true;
        }
      });
      return num >= 2;
    },
    content() {
      'step 0';
      const targets = game.filterPlayer();
      targets.remove(player);
      targets.sort(lib.sort.seat);
      event.targets = targets;
      event.count = Math.min(trigger.num, 9);
      ('step 1');
      event.num = 0;
      player.line(targets, 'green');
      player
        .chooseControl('手牌区', '装备区', '判定区')
        .set('ai', function () {
          if (
            game.hasPlayer(function (current) {
              return current.countCards('j') && current != player && get.attitude(player, current) > 0;
            })
          ) {
            return 2;
          }
          return Math.floor(Math.random() * 3);
        })
        .set('prompt', '请选择优先获得的区域');
      ('step 2');
      event.range = {
        手牌区: ['h', 'e', 'j'],
        装备区: ['e', 'h', 'j'],
        判定区: ['j', 'h', 'e'],
      }[result.control || '手牌区'];
      ('step 3');
      if (num < event.targets.length) {
        const target = event.targets[num];
        const range = event.range;
        for (const i of range) {
          const cards = target.getCards(i);
          if (cards.length) {
            const card = cards.randomGet();
            player.gain(card, target, 'giveAuto', 'bySelf');
            break;
          }
        }
        event.num++;
      }
      ('step 4');
      if (num < event.targets.length) {
        event.goto(3);
      }
      ('step 5');
      player.turnOver();
      ('step 6');
      event.count--;
      if (event.count) {
        player.chooseBool(get.prompt2('shanhe_guixin')).ai = function () {
          return lib.skill.shanhe_guixin.check({ num: event.count }, player);
        };
      } else {
        event.finish();
      }
      ('step 7');
      if (event.count && result.bool) {
        event.goto(1);
      }
    },
    ai: {
      maixie: true,
      maixie_hp: true,
      threaten(player, target) {
        if (target.hp == 1) {
          return 2.5;
        }
        return 1;
      },
      effect: {
        target(card, player, target) {
          if (get.tag(card, 'damage')) {
            if ((player.hasSkillTag('jueqing', false, target) || player.hasSkill('shanhe_zhangdu')) && get.tag(card, 'damage')) {
              return [1, -2];
            }
            if (target.hp == 1) {
              return 0.8;
            }
            if (target.isTurnedOver()) {
              return [0, 3];
            }
            const num = game.countPlayer(function (current) {
              if (current.countCards('he') && current != player && get.attitude(player, current) <= 0) {
                return true;
              }
              if (current.countCards('j') && current != player && get.attitude(player, current) > 0) {
                return true;
              }
            });
            if (num > 2) {
              return [0, 1];
            }
            if (num == 2) {
              return [0.5, 1];
            }
          }
        },
      },
    },
  },
