            current.directgain(get.cards(guankajisuan == 2 ? 1 : guankajisuan == 3 || guankajisuan == 4 ? 2 : guankajisuan == 5 || guankajisuan == 6 ? 4 : guankajisuan == 7 || guankajisuan == 8 ? 6 : 8));
            current.addSkill('ts_kuangbao');
