  fhlt_zhanxiang: {
    enable: 'phaseUse',
    viewAs: { name: 'nanman' },
    filterCard(card, player) {
      if (!ui.selected.cards.length) {
        return !player.storage.fhlt_zhanxiang || (player.storage.fhlt_zhanxiang && !player.storage.fhlt_zhanxiang.includes(card.suit));
      }
      if (ui.selected.cards.length) {
        return card.suit == ui.selected.cards[0].suit;
      }
      const cards = player.getCards('hs');
      if (Array.isArray(cards)) {
        for (const i of cards) {
          if (card != i) {
            if (card.suit == i.suit) {
              return true;
            }
          }
        }
      }
      return false;
    },
    position: 'hs',
    selectCard: 2,
    check(card) {
      const player = _status.event.player;
      const targets = game.filterPlayer(function (current) {
        return player.canUse('nanman', current);
      });
      let num = 0;
      for (const i of targets) {
        let eff = get.sgn(get.effect(i, { name: 'nanman' }, player, player));
        if (i.hp == 1) {
          eff *= 1.5;
        }
        num += eff;
      }
      if (!player.needsToDiscard(-1)) {
        if (targets.length >= 7) {
          if (num < 2) {
            return 0;
          }
        } else if (targets.length >= 5) {
          if (num < 1.5) {
            return 0;
          }
        }
      }
      return 6 - get.value(card);
    },
    ai: {
      basic: {
        order: 8.9,
      },
    },
    group: ['fhlt_zhanxiang_count', 'fhlt_zhanxiang_reset'],
    subSkill: {
      reset: {
        trigger: { global: 'phaseAfter' },
        forced: true,
        charlotte: true,
        silent: true,
        filter(event, player) {
          return player.storage.fhlt_zhanxiang;
        },
        content() {
          delete player.storage.fhlt_zhanxiang;
        },
      },
      count: {
        trigger: { player: 'useCard' },
        forced: true,
        charlotte: true,
        silent: true,
        filter(event, player) {
          return event.skill == 'fhlt_zhanxiang';
        },
        content() {
          if (!player.storage.fhlt_zhanxiang) {
            player.storage.fhlt_zhanxiang = [];
          }
          if (Array.isArray(trigger.cards)) {
            for (const i of trigger.cards) {
              player.storage.fhlt_zhanxiang.add(i.suit);
            }
          }
        },
      },
    },
  },
